package com.nequard.organization; import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/v1/organizations") public class OrganizationController{private final OrganizationRepository repo;public OrganizationController(OrganizationRepository r){repo=r;}record Request(@NotBlank String name,@NotBlank String slug){}@GetMapping public List<Organization> all(){return repo.findAll();}@GetMapping("/{id}")public ResponseEntity<Organization> one(@PathVariable UUID id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}@PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN')")public ResponseEntity<?> create(@RequestBody @Valid Request r){if(repo.existsBySlug(r.slug()))return ResponseEntity.status(409).body(Map.of("error","SLUG_EXISTS"));Organization o=new Organization();o.setName(r.name());o.setSlug(r.slug());return ResponseEntity.status(201).body(repo.save(o));}}